test("行内のアイコンのボタンは、中身の綴りではなく与えた名前で読まれる", () => {
  render(
    <Button kind={ButtonKinds.InlineIcon} aria-label="等倍に戻す">
      55%
    </Button>,
  );

  expect(screen.getByRole("button", { name: "等倍に戻す" })).toBeDefined();
});

test("行内のアイコンは、名前を与えないと型エラーになる", () => {
  // @ts-expect-error 中身の記号・数値は操作を言い表さないので aria-label が要る
  const props: ButtonProps = { kind: ButtonKinds.InlineIcon, children: "+" };

  expect(props.kind).toBe(ButtonKinds.InlineIcon);
});

test("行内のアイコンには大きさを渡せない", () => {
  // @ts-expect-error 行内のアイコンは置いた行の字の大きさを継ぎ、高さを持たない
  const props: ButtonProps = {
    kind: ButtonKinds.InlineIcon,
    "aria-label": "追加",
    size: ButtonSizes.Regular,
    children: "+",
  };

  expect(props.kind).toBe(ButtonKinds.InlineIcon);
});

test("拡大を押すと倍率が上がる", async () => {
  renderTopBar({ zoom: true });

  await userEvent.click(screen.getByRole("button", { name: "拡大" }));

  expect(screen.getByRole("button", { name: "等倍に戻す" }).textContent).toBe(
    "120%",
  );
});

test("縮小を押すと倍率が下がる", async () => {
  renderTopBar({ zoom: true });

  await userEvent.click(screen.getByRole("button", { name: "縮小" }));

  expect(screen.getByRole("button", { name: "等倍に戻す" }).textContent).toBe(
    "83%",
  );
});

test("倍率を押すと等倍に戻る", async () => {
  renderTopBar({ zoom: true });
  await userEvent.click(screen.getByRole("button", { name: "拡大" }));

  await userEvent.click(screen.getByRole("button", { name: "等倍に戻す" }));

  expect(screen.getByRole("button", { name: "等倍に戻す" }).textContent).toBe(
    "100%",
  );
});

test("stop が 2 件なら stop の − は押せない", () => {
  renderGradient(TwoStops);

  expect(
    screen.getByRole<HTMLButtonElement>("button", { name: "stop 1 を削除" })
      .disabled,
  ).toBe(true);
});

test("stop が 3 件なら stop の − を押すとその stop を除いた値が別のまとまりで届く", async () => {
  const user = userEvent.setup();
  const onSetTokenValue = renderGradient(ThreeStops);

  await user.click(screen.getByRole("button", { name: "stop 2 を削除" }));

  expect(onSetTokenValue).toHaveBeenCalledWith(
    {
      kind: "gradients",
      value: {
        shape: "linear",
        angle: 90,
        stops: [ThreeStops[0], ThreeStops[2]],
      },
    },
    EditContinuities.Separate,
  );
});

test("stop を追加すると stop を足した値が別のまとまりで届く", async () => {
  const user = userEvent.setup();
  const onSetTokenValue = renderGradient(TwoStops);

  await user.click(screen.getByRole("button", { name: "stop を追加" }));

  expect(onSetTokenValue).toHaveBeenCalledWith(
    {
      kind: "gradients",
      value: {
        shape: "linear",
        angle: 90,
        stops: [
          { color: "#000000", ratio: 0 },
          { color: "#000000", ratio: 0.5 },
          { color: "#ffffff", ratio: 1 },
        ],
      },
    },
    EditContinuities.Separate,
  );
});

test("開いている種別には追加ボタンが出る", () => {
  renderList();

  expect(
    screen.getByRole("button", { name: "colors にトークンを追加" }),
  ).toBeDefined();
});

test("追加のボタンを押すとキャンバスに artboard が1枚増える", async () => {
  await renderOpenedDocument();

  await userEvent.click(
    within(artboardList()).getByRole("button", { name: "artboard を追加" }),
  );

  expect(canvasArtboardNames()).toEqual(["home", "settings", "artboard"]);
});

test("stop を追加すると 3 件になり、Ctrl+Z 1 回で 2 件へ戻る", async () => {
  await addGradient();

  await userEvent.click(
    within(propertyPane()).getByRole("button", { name: "stop を追加" }),
  );
  // 足せたことを先に見る。足せていないと Ctrl+Z が no-op でも最後の assert が通る。
  expect(row(/^gradient 90° · 3 stops$/)).toBeDefined();
  blurActive();

  await userEvent.keyboard("{Control>}z{/Control}");

  expect(row(/^gradient 90° · 2 stops$/)).toBeDefined();
});

